// Every beat is $1C on the chip -- one volume, no accents.
const MARIO1_TRK4_ACCENTS: number[] = Array.from({ length: 3840 }, () => 0);


const EMPTY_GRID_3840: number[][] = Array.from({ length: 3840 }, () => []);
const EMPTY_ACCENTS_3840: number[] = Array.from({ length: 3840 }, () => 0);

const GRIDS: Record<number, number[][]> = {
  0: MARIO1_TRK1_GRID,
  1: MARIO1_TRK2_GRID,
  3: MARIO1_TRK4_GRID,
  4: MARIO1_TRK5_GRID,
};

/* The noise channel, generated from the ROM rather than transcribed. The
   game's NoiseBeatHandler (smbdis.asm) knows three beats, each a fixed
   register triplet:

     short   $400C=$1C  $400E=$03  $400F=$18   white noise,  2 frames ( 33 ms)
     strong  $400C=$1C  $400E=$0C  $400F=$18   low noise,    2 frames ( 33 ms)
     long    $400C=$1C  $400E=$03  $400F=$58   white noise, 10 frames (167 ms)

   $1C is volume 12 with the envelope off: a flat burst the length counter
   cuts dead. Period $03 clocks the LFSR at 56 kHz, flat across the band;
   $0C at 2.3 kHz, a thud with almost nothing above 1.5 kHz.

   The grid comes from walking the ground-music header sequence (lead-in,
   P1 x2, [2A 2B 2A 2C] x2, 3A 3B 3A lead-in, P1 x2, [4A 4B 4A 4C] x2, 3A 3B
   3A lead-in, 4A 4B 4A 4C, then back to P1) and, per section, its noise
   data from the header's noise offset, looping at $00. Every length is a
   multiple of 3 frames = 2 steps, so it sits exactly on this grid. The
   part-1 loop is 72 frames -- a bar and a half -- so its accents drift
   half a bar against the melody until the next section header resets
   them; that drift is the feel the transcription had flattened out.
   Generator: scripts/gen-smb1-trk4.py.

   Runs: long beats are 7 steps (the hardware's 167 ms), short and strong
   beats 2 steps. The hits decay on their own, so the run is what the roll
   shows rather than what the ear gets. */
/* Voicing. The chip plays all three as bursts of one noise generator, but
   the ear files them as a kit: the long beat sits on 2 and 4 and reads as
   a snare, the short ones as hats, the strong one as a low kick.

   Tuned against the original recording: reference hits were cut out at the
   ROM-predicted positions (16 hats, 8 snares, 8 kicks in the first two
   part-1 sections), reduced to a 40-band log spectrum with the sustaining
   channels subtracted plus a band-limited RMS envelope, and each candidate
   here was rendered offline and correlated with that. The hat wants no
   high-pass at all (full-band noise, spectral r = 0.77 vs 0.12 with the 80
   Hz HPF it used to have); the kick's low-pass at KEY TRK 1 (r = 0.88); the
   snare's first tuned version (a 40% triangle body held at 60% over the
   run, envelope r = 0.85 against the reference) was rejected by ear as a
   tuned boing, so it is a decaying noise hit with no tonal part at all. Every hit starts on its
   first sample. */
const NES_HAT: Partial<TrackData> = {
  osc1Waveform: 'noise', osc1Gain: 1.0,
  osc2Waveform: 'triangle', osc2Gain: 0.0, osc2Ratio: 1, detuneCents: 0, phaseOffset: 0, osc2Semitone: 0,
  pulseWidth: 50, subOscGain: 0.0, noiseGain: 0.0, noiseRetrig: 1, noiseRetrigGap: 12,
  blendMode: 'layer', morphAmount: 0.0, glideTime: 0, xfade: 0.5,
  filterType: 'lowpass', cutoff: 12000, resonance: 0.2, envFilterMod: 0.0, keyTracking: 0.8,
  attack: 0, decay: 0.1, sustain: 0.0, release: 0.04,
  ampAttack: 0, ampDecay: 0.1, ampSustain: 0.0, ampRelease: 0.04,
  filterAttack: 0, filterDecay: 0.06, filterSustain: 0.0, filterRelease: 0.03, filterEnvAmount: 0.0,
  pitchAttack: 0.001, pitchDecay: 0.04, pitchEnvAmount: 0.0,
  lfoWaveform: 'sine', lfoRate: 1.0, lfoPitchAmt: 0.0, lfoCutoffAmt: 0.0, lfoPanAmt: 0.0, lfoAmpAmt: 0.0, lfoFadeTime: 0,
  airGain: 0.0,
};

export const SMB1_NOISE_KEYS: Record<number, Partial<TrackData>> = {
  // F3: hat -- the track's own sound; the entry exists so the key shows as part of the kit.
  55: { ampDecay: 0.1, decay: 0.1 },
  // D3: snare. Noise only -- no body, no pitch snap, nothing that follows
  // the key -- starting on its first sample and decaying over 180 ms. What
  // separates it from the hat is length and a darker top (6 kHz low-pass).
  58: {
    osc1Waveform: 'noise', osc1Gain: 1.0, osc2Gain: 0.0, osc2Semitone: 0,
    noiseGain: 0.0, keyTracking: 0.0,
    filterType: 'lowpass', cutoff: 6000, resonance: 0.3,
    filterEnvAmount: 0.0, filterAttack: 0, filterDecay: 0.08, filterSustain: 0.0,
    pitchEnvAmount: 0.0, pitchAttack: 0.001, pitchDecay: 0.02,
    ampAttack: 0, attack: 0, ampDecay: 0.18, decay: 0.18, ampSustain: 0.0, sustain: 0.0, ampRelease: 0.05, release: 0.05, airGain: 0.0,
  },
  // C3: the strong beat -- KEY TRK 1 at C3 halves the noise rate and scales
  // the low-pass to ~2.4 kHz, the nearest this engine gets to the 2.3 kHz
  // LFSR without losing the level (a 1.2 kHz cut sat 8 dB under the hat).
  60: {
    keyTracking: 1, filterType: 'lowpass', cutoff: 4800, resonance: 1.0, pitchEnvAmount: 0.0,
    ampDecay: 0.12, decay: 0.12, ampRelease: 0.02, release: 0.02,
  },
};

// Same 6-track kit as the SMB3 songs — loadBuiltInSong deep-copies, so sharing
// the track parameter objects here is safe. TRK 4 is the exception: it is the
// NES noise channel in percussion mode, one sound per key.
/* Sidechain, per track, keyed to TRK 4's kit: the bass ducks on the kick (C3),
   the harmony on the snare (D3), the pad on every hit; the lead stays steady.
   Set for every track because OVERWORLD_TRACKS carries SMB3's own keys. */
const OFF = { duckSource: -1, duckKey: -1, duckDepth: 0 };
const MARIO1_DUCK: Record<number, Partial<TrackData>> = {
  0: OFF,
  1: { duckSource: 3, duckKey: 58, duckDepth: 0.3, duckDip: 3, duckHold: 40, duckRelease: 100 },
  2: { duckSource: 3, duckKey: -1, duckDepth: 0.35, duckDip: 5, duckHold: 20, duckRelease: 80 },
  3: OFF,
  4: { duckSource: 3, duckKey: 60, duckDepth: 0.55, duckDip: 3, duckHold: 30, duckRelease: 90 },
  5: OFF,
};

export const MARIO1_TRACKS: TrackData[] = OVERWORLD_TRACKS.map((t) => ({
  ...t,
  ...(MARIO1_DUCK[t.id] ?? OFF),
  ...(t.id === 3 ? { ...NES_HAT, percussion: true, keyTimbres: SMB1_NOISE_KEYS } : {}),
  grid: GRIDS[t.id] ?? EMPTY_GRID_3840,
  accents: t.id === 3 ? MARIO1_TRK4_ACCENTS : EMPTY_ACCENTS_3840,
}));
